package gamejampromo

const adminHTML = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Ruleshift Game Jam Promotions</title>
<style>
:root{color-scheme:dark;--ink:#171714;--panel:#24231f;--line:#565247;--paper:#f3eedf;--yellow:#f5e642;--cyan:#42d9e8;--red:#ff625f}*{box-sizing:border-box}body{margin:0;background:var(--ink);color:var(--paper);font:14px system-ui,sans-serif}header{position:sticky;top:0;z-index:5;display:flex;justify-content:space-between;align-items:center;padding:18px 24px;border-bottom:2px solid var(--paper);background:var(--ink)}h1{margin:0;font-size:18px;letter-spacing:.08em}button,input,select{font:inherit}button{min-height:38px;border:2px solid var(--paper);padding:0 14px;background:transparent;color:var(--paper);cursor:pointer;font-weight:750}button:hover{background:var(--yellow);color:var(--ink)}button.danger:hover{background:var(--red)}main{width:min(1240px,calc(100% - 32px));margin:28px auto 80px}.toolbar{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:18px}.toolbar select{min-height:40px}.status{color:#9d988a}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(360px,1fr));gap:14px}.card{border:2px solid var(--line);padding:16px;background:var(--panel)}.card.changed{border-color:var(--yellow)}.meta{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px}.tag{padding:4px 7px;background:#35332d;color:var(--cyan);font:11px ui-monospace,monospace}.fields{display:grid;grid-template-columns:1fr 1fr;gap:9px}.fields label{display:grid;gap:4px;color:#aaa496;font-size:11px}.fields .wide{grid-column:1/-1}.fields input,.fields select{width:100%;min-height:38px;border:1px solid var(--line);padding:0 9px;background:var(--ink);color:var(--paper)}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}.source{display:block;margin:10px 0;color:var(--cyan);overflow-wrap:anywhere}.code{margin:12px 0;padding:12px;border:1px dashed var(--cyan);font:20px ui-monospace,monospace;letter-spacing:.14em}.runs{margin-top:32px;border-top:2px solid var(--line);padding-top:22px}.run{display:grid;grid-template-columns:130px 1fr 90px;gap:12px;padding:8px 0;border-bottom:1px solid #38362f;font:12px ui-monospace,monospace}.empty{padding:40px;border:2px dashed var(--line);text-align:center;color:#8f8a7e}@media(max-width:600px){header{align-items:flex-start;gap:12px}.fields{grid-template-columns:1fr}.fields .wide{grid-column:auto}.grid{grid-template-columns:1fr}.run{grid-template-columns:1fr}}
</style>
</head>
<body>
<header><div><h1>RULESHIFT / GAME JAM PROMOTIONS</h1><span class="status" id="status">Loading…</span></div><button id="sync">RUN DISCOVERY</button></header>
<main>
<section>
<div class="toolbar">
<select id="source"><option value="">ALL SOURCES</option><option value="gamedev_afisha">AFISHA</option><option value="jammer">JAMMER</option><option value="itch_io">ITCH.IO</option></select>
<select id="format"><option value="">ALL FORMATS</option><option>online</option><option>offline</option><option>hybrid</option><option>unknown</option></select>
<select id="relevance"><option value="likely_ru">LIKELY RU</option><option value="unknown">UNKNOWN</option><option value="unlikely_ru">UNLIKELY RU</option><option value="">ALL RELEVANCE</option></select>
<select id="candidate-status"><option value="pending">PENDING</option><option value="approved">APPROVED</option><option value="rejected">REJECTED</option><option value="archived">ARCHIVED</option><option value="">ALL STATUS</option></select>
<button id="reload">RELOAD</button>
</div>
<div class="grid" id="candidates"></div>
</section>
<section class="runs"><h2>APPROVED GAME JAMS</h2><div class="grid" id="gamejams"></div></section>
<section class="runs"><h2>DISCOVERY RUNS</h2><div id="runs"></div></section>
</main>
<script>
const byId=(id)=>document.getElementById(id);
let gameJamItems=[];
async function api(path,options={}){const response=await fetch(path,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});if(!response.ok){throw new Error((await response.json().catch(()=>({}))).code||('HTTP '+response.status));}if(response.status===204)return null;return response.json();}
function isoDate(value){return String(value||'').slice(0,10)}
function input(label,name,type='text'){const wrap=document.createElement('label');wrap.textContent=label;const field=document.createElement('input');field.name=name;field.type=type;wrap.append(field);return wrap}
function selectField(label,name,values){const wrap=document.createElement('label');wrap.textContent=label;const field=document.createElement('select');field.name=name;values.forEach(v=>{const option=document.createElement('option');option.value=v;option.textContent=v;field.append(option)});wrap.append(field);return wrap}
function tag(value){const span=document.createElement('span');span.className='tag';span.textContent=value;return span}
async function load(){byId('status').textContent='Loading data…';try{await loadGameJams();await Promise.all([loadCandidates(),loadRuns()]);byId('status').textContent='Updated '+new Date().toLocaleTimeString();}catch(error){byId('status').textContent='Error: '+error.message}}
async function loadCandidates(){const params=new URLSearchParams();['source','format','relevance'].forEach(id=>{if(byId(id).value)params.set(id,byId(id).value)});if(byId('candidate-status').value)params.set('status',byId('candidate-status').value);const data=await api('/admin/api/v1/candidates?'+params);const root=byId('candidates');root.replaceChildren();if(!data.items.length){root.append(Object.assign(document.createElement('div'),{className:'empty',textContent:'NO CANDIDATES'}));return}data.items.forEach(item=>root.append(candidateCard(item)))}
function candidateCard(item){const card=document.createElement('article');card.className='card'+(item.source_changed?' changed':'');const meta=document.createElement('div');meta.className='meta';[item.source,item.format,item.relevance,item.status].forEach(v=>meta.append(tag(v)));if(item.source_changed)meta.append(tag('SOURCE UPDATE'));card.append(meta);[item.source_url,item.official_url].filter((v,i,a)=>v&&a.indexOf(v)===i).forEach((href,index)=>{const source=document.createElement('a');source.className='source';source.target='_blank';source.rel='noreferrer';source.href=href;source.textContent=(index?'OFFICIAL: ':'SOURCE: ')+href;card.append(source)});const suggestions=[item.exact_duplicate_game_jam_id,...(item.possible_duplicate_game_jam_ids||[])].filter((v,i,a)=>v&&a.indexOf(v)===i);if(suggestions.length){const duplicate=document.createElement('p');duplicate.className='status';duplicate.textContent=(item.exact_duplicate_game_jam_id?'EXACT OFFICIAL URL MATCH: ':'POSSIBLE DUPLICATE: ')+suggestions.join(', ');card.append(duplicate)}const approved=gameJamItems.find(v=>v.id===item.linked_game_jam_id);if(item.source_changed&&approved){const pairs={title:[approved.title,item.title],organizer:[approved.organizer||'',item.organizer||''],format:[approved.format,item.format],city:[approved.city||'',item.city||''],country:[approved.country_code||'',item.country_code||''],languages:[(approved.languages||[]).join(', '),(item.languages||[]).join(', ')],starts_on:[isoDate(approved.starts_on),isoDate(item.starts_on)],ends_on:[isoDate(approved.ends_on),isoDate(item.ends_on)]};const changed=Object.entries(pairs).filter(([,v])=>v[0]!==v[1]);const diff=document.createElement('p');diff.className='status';diff.textContent='SOURCE DIFF: '+changed.map(([k,v])=>k+' ['+v[0]+' → '+v[1]+']').join(' | ');card.append(diff)}const fields=document.createElement('div');fields.className='fields';fields.append(input('OFFICIAL URL','official_url'),input('TITLE','title'),input('ORGANIZER','organizer'),selectField('FORMAT','format',['online','offline','hybrid','unknown']),input('CITY','city'),input('COUNTRY','country_code'),input('LANGUAGES (comma)','languages'),input('START','starts_on','date'),input('END','ends_on','date'),selectField('RELEVANCE','relevance',['likely_ru','unknown','unlikely_ru']));card.append(fields);const values={official_url:item.official_url||'',title:item.title,organizer:item.organizer||'',format:item.format,city:item.city||'',country_code:item.country_code||'',languages:(item.languages||[]).join(', '),starts_on:isoDate(item.starts_on),ends_on:isoDate(item.ends_on),relevance:item.relevance};Object.entries(values).forEach(([key,value])=>{fields.querySelector('[name="'+key+'"]').value=value});const actions=document.createElement('div');actions.className='actions';actions.append(button('SAVE',()=>saveCandidate(item.id,fields)));if(item.status==='pending'){const reason=selectField('','reason',['venue_ru','language_ru','audience_ru','organizer_ru']).querySelector('select');actions.append(reason,button('APPROVE',()=>approveCandidate(item.id,reason.value)),button('REJECT',()=>rejectCandidate(item.id),'danger'),button('MERGE',()=>mergeCandidate(item.id,suggestions[0]||'')))}if(item.source_changed&&item.linked_game_jam_id){actions.append(button('APPLY SOURCE UPDATE',()=>reviewCandidateUpdate(item.id,true)),button('KEEP SNAPSHOT',()=>reviewCandidateUpdate(item.id,false),'danger'))}card.append(actions);return card}
function button(text,handler,className=''){const value=document.createElement('button');value.textContent=text;value.className=className;value.addEventListener('click',handler);return value}
function candidateBody(fields){const get=name=>fields.querySelector('[name="'+name+'"]').value;return{official_url:get('official_url'),title:get('title'),organizer:get('organizer'),format:get('format'),city:get('city'),country_code:get('country_code'),languages:get('languages').split(',').map(v=>v.trim()).filter(Boolean),starts_on:get('starts_on'),ends_on:get('ends_on'),relevance:get('relevance')}}
async function saveCandidate(id,fields){await api('/admin/api/v1/candidates/'+id,{method:'PATCH',body:JSON.stringify(candidateBody(fields))});await loadCandidates()}
async function approveCandidate(id,reason){const value=await api('/admin/api/v1/candidates/'+id+'/approve',{method:'POST',body:JSON.stringify({reason})});alert('Code for '+value.title+': '+value.code);await load()}
async function rejectCandidate(id){const reason=prompt('Rejection reason');if(!reason)return;await api('/admin/api/v1/candidates/'+id+'/reject',{method:'POST',body:JSON.stringify({reason})});await loadCandidates()}
async function mergeCandidate(id,suggestion=''){const game_jam_id=prompt('Existing game jam ID',suggestion);if(!game_jam_id)return;await api('/admin/api/v1/candidates/'+id+'/merge',{method:'POST',body:JSON.stringify({game_jam_id})});await load()}
async function reviewCandidateUpdate(id,apply){await api('/admin/api/v1/candidates/'+id+'/review-update',{method:'POST',body:JSON.stringify({apply})});await load()}
async function loadGameJams(){const data=await api('/admin/api/v1/gamejams');gameJamItems=data.items;const root=byId('gamejams');root.replaceChildren();if(!data.items.length){root.append(Object.assign(document.createElement('div'),{className:'empty',textContent:'NO APPROVED GAME JAMS'}));return}data.items.forEach(item=>root.append(gameJamCard(item)))}
function gameJamCard(item){const card=document.createElement('article');card.className='card';const title=document.createElement('h3');title.textContent=item.title;card.append(title);const meta=document.createElement('div');meta.className='meta';[item.id,item.format,item.status,item.eligibility_reason].forEach(v=>meta.append(tag(v)));card.append(meta);const fields=document.createElement('div');fields.className='fields';fields.append(input('TITLE','title'),input('ORGANIZER','organizer'),selectField('FORMAT','format',['online','offline','hybrid','unknown']),input('CITY','city'),input('COUNTRY','country_code'),input('LANGUAGES (comma)','languages'),input('START','starts_on','date'),input('END','ends_on','date'),selectField('STATUS','status',['approved','disabled','ended']));card.append(fields);const values={title:item.title,organizer:item.organizer||'',format:item.format,city:item.city||'',country_code:item.country_code||'',languages:(item.languages||[]).join(', '),starts_on:isoDate(item.starts_on),ends_on:isoDate(item.ends_on),status:item.status};Object.entries(values).forEach(([key,value])=>{fields.querySelector('[name="'+key+'"]').value=value});const code=document.createElement('div');code.className='code';code.textContent=item.code||('••••••'+item.code_last_four);card.append(code);const actions=document.createElement('div');actions.className='actions';actions.append(button('SAVE',()=>saveGameJam(item.id,fields)),button('COPY',()=>navigator.clipboard.writeText(item.code)),button('ROTATE',()=>rotateCode(item.id),'danger'),button(item.status==='approved'?'DISABLE':'ENABLE',()=>toggleJam(item)));card.append(actions);return card}
function gameJamBody(fields){const get=name=>fields.querySelector('[name="'+name+'"]').value;return{title:get('title'),organizer:get('organizer'),format:get('format'),city:get('city'),country_code:get('country_code'),languages:get('languages').split(',').map(v=>v.trim()).filter(Boolean),starts_on:get('starts_on'),ends_on:get('ends_on'),status:get('status')}}
async function saveGameJam(id,fields){await api('/admin/api/v1/gamejams/'+id,{method:'PATCH',body:JSON.stringify(gameJamBody(fields))});await load()}
async function rotateCode(id){if(!confirm('Revoke the current code and issue a new one?'))return;const value=await api('/admin/api/v1/gamejams/'+id+'/rotate-code',{method:'POST',body:'{}'});alert('New code: '+value.code);await loadGameJams()}
async function toggleJam(item){const body={title:item.title,organizer:item.organizer||'',format:item.format,city:item.city||'',country_code:item.country_code||'',languages:item.languages||[],starts_on:isoDate(item.starts_on),ends_on:isoDate(item.ends_on),status:item.status==='approved'?'disabled':'approved'};await api('/admin/api/v1/gamejams/'+item.id,{method:'PATCH',body:JSON.stringify(body)});await loadGameJams()}
async function loadRuns(){const data=await api('/admin/api/v1/discovery/runs');const root=byId('runs');root.replaceChildren();data.items.forEach(item=>{const row=document.createElement('div');row.className='run';[item.source,item.result+' · '+item.found_count,new Date(item.started_at).toLocaleString()].forEach(v=>{const span=document.createElement('span');span.textContent=v;row.append(span)});if(item.message){const msg=document.createElement('span');msg.textContent=item.message;msg.style.gridColumn='1/-1';row.append(msg)}root.append(row)})}
byId('reload').addEventListener('click',load);['source','format','relevance','candidate-status'].forEach(id=>byId(id).addEventListener('change',loadCandidates));byId('sync').addEventListener('click',async()=>{await api('/admin/api/v1/discovery/run',{method:'POST',body:'{}'});byId('status').textContent='Discovery started';setTimeout(loadRuns,1500)});load();
</script>
</body>
</html>`
